util='Data/Scripts/013_Items/001_Item_Utilities.rb'
u('X01',util,1,128,A,'§4.3/§4.4/§7',normal,'Bag/Party处理器','背包Use资格是三种out处理器并集，Register资格只野外处理器。','个体最大数量缺处理器或配置关返1，其余至少1；实际数量由调用入口再与袋总量取小。')
u('X02',util,129,581,A,'§4.2/§4.4/§7',normal,'成长/HP/PP及场地工具','等级/Exp工具先钳合法域，实际写/重算/刷新/消息/学习进化按入口顺序，不把后置显示失败回滚。','奶招HP helper对目标恢复上钳total，返实际delta；源仍扣固定用量。','PP恢复需存在招/正上限并上钳，mint及EV工具有各自确认/写入序；非本片主合同归WP28，完整源已读。','自行车资格按当前地图/地形/跟随者门，Itemfinder当前图范围与最近点；其领域链只有限接合WP28/59，未扩大整域。')
u('X03',util,582,639,A,'§7.1/§6.5',normal,'教学→Move/Summary/幸福','蛋非debug与Shadow拒，已会false，空槽直接追加新记录。','满招先确认，选定整体替换；机器配置开才min旧PP/新上限，成功替换后机器友好度。','遗忘取消再确认放弃，No重选，Yesfalse；HM门由Summary遗忘处理。')
u('X04',util,640,780,C,'§4/§6.4',normal,'Bag/Party→效果→扣减','Bag目标循环先非蛋计数，取消覆盖ret=false，前次效果/库存不回滚。','Bag个体效果true且consumable才扣传入数量，移除返回不检；最后一份消息后退出。','Bag直接/机器返回1时扣一、2不在内层扣；外层field独立执行。','Party直接机器有Shadow/兼容/确认；成功才consumable扣一，无Bag机器统计/first_moves包装。','Party一般效果后先清注解/硬刷新，再消费；可重入形态读取，未知不当纯显示。')
u('X05',util,781,917,A,'§4.4/§4.5/§4.6',normal,'持物/邮件→Bag/PC','Give蛋拒，旧邮件先取回成功才能后续，取回前缀不回滚。','交换先删新物再旧物入袋；旧物入袋失败尝试还新，无法还异常。','交换新邮件写作放弃还新但不删已入袋旧物，源仍持旧；总旧物可净+1。','Take先查Bag容量，PC/销毁两确认不同；先添加/提示后清持物，消息失败可保前缀。','选择通用/apricorn/fossil与显式列表事件助手有取消编码；正常过滤包装恢复游标。')
u('X06','Data/Scripts/016_UI/022_UI_MoveRelearner.rb',1,199,A,'§7.3',normal,'提醒候选→首绘→学习/计数','蛋/Shadow候选空，等级≤当前未会且身份首现去重。','更多开时first_moves独有未会项前置，重叠项留原等级位置，最后去重。','启动首绘严格查询选中候选，空数组首项nil的Move.get类型验证先失败，无BACK窗口。','非空USE确认教学，核心成功才reminder统计+1/true并关；核心false回列表；BACK确认放弃true才false并关。')
u('X07','Data/Scripts/013_Items/008_PokemonBag.rb',1,301,C,'§3/§5/§6.4',normal,'容器生产/保存→UI','袋构造各口袋与索引0，last pocket1，登记为空。','索引读取min保存值/袋长，写入只验上限；注册去重，无库存/使用资格内门。','can_add纯预演，add/remove可部分改后false；add成功自动排序按登记顺序。','普通rollback从首匹配槽删，故[999,997]加2后删2成为[997,999]，不是槽快照。','PC999槽/每槽999，懒构造按起始物品数据播种；负数量异常、0成功不改。')
u('X08','Data/Scripts/014_Pokemon/001_Pokemon-related/004_PokemonStorage.rb',1,400,BB,'§2–§4/§8',normal,'storage→UI/捕获','默认盒6x5、40盒，currentBox0，基础墙纸16，special解锁数组。','基础仅-1队伍，其余负数数组寻址；maxPokemon负盒却返队伍上限，不可概括全部伪位置安全。','移动=copy成功后删源，入队追加并压缩，入盒首空；存入治疗保ready_evolve。','捕获先当前盒再其余盒，成功更新currentBox；全满-1。','Regional代理move误用copy、delete未定义参数等有定义行为但本主UI用基础storage，不授区域代理正常运行。')
u('X09','Data/Scripts/013_Items/007_Item_Sprites.rb',1,157,C,'§3.1 图标附表',normal,'袋/摘要/PC/商店/Party图标','道具高48才横向48方格，帧数floor宽/48至少1，周期1秒；其他高整图单帧。','空item在blankzero真隐藏，否则请求通用返回图；摘要设隐藏，其他主UI空选择请求图。','帧以绝对uptime相位，不以新建清0；持物图随成员item_id改变刷新，无物bitmapnil。')
u('X10','Data/Scripts/014_Pokemon/001_Pokemon-related/003_Pokemon_Sprites.rb',1,316,C,'§3.1 图标附表',normal,'Party/Summary/Dex资源请求','个体图调用Species资源选择且可触发成员form读取。','个体图标方格边长图高，常态0.25秒，HP≤半0.5、≤四分之一1秒，濒死首帧。','选中x+4，帧≥floor(N/2)时y-2否则+6；物种图标0.25无HP门，均绝对相位。','空个体bitmapnil；资源请求与宿主最终图像分层。')
u('X11','Data/Scripts/013_Items/006_Item_Mail.rb',1,125,A,'§4.4/§4.5/§6.4',normal,'Mail→邮箱/读取UI','邮箱未满10且成员有邮件才压入同一对象并清成员mail。','新邮件挂对象不自动设置持物，mail getter可因无匹配item自清。','写作250上限，非空时先取玩家队伍k+2/k+1，再实际目标字段快照；空文须确认放弃。','阅读依保存的三项身份快照请求图标、显示正文/署名，USE/BACK关闭，不重拍/不写。')
u('X12','Data/Scripts/016_UI/024_UI_MysteryGift.rb',1,428,C,'§4 Debug/§11',normal,'Bag Debug→礼物文件/下载/领取','Debug物品从数量1编辑，范围1..99999、ID去重、名250；取消不生成礼物，已有对象编辑可有前缀。','create正常编码后写Master，错误消息不把已写文件回滚；本次没有执行网络/文件业务。','下载去已拥有ID，动画/两接收消息后才push gift；网络返回/解码与媒体均未执行。','领取个体先重随机ID/重算/日期/获得/初始招记录，add成功消息后把gift改已领；条件简略图鉴链。','物品领取先can_add再add，消息后已领标记；字段/序列化安全层归WP64/Kernel，本片不审批无界外部输入。')
u('X13','Data/Scripts/016_UI/023_UI_PurifyChamber.rb',284,631,BB,'§2.2/§12',normal,'storage选择返回→Purify direct consumer','Helper分中心/环成员/环间空位，放入按Shadow/普通/蛋门。','pbPlacePokemon读取原始storage位置，放入成功后删除同原始位置，没有最后可用门。','Replace按新旧Shadow相同确认后把chamber与storage位置交换。','Choose成员分支持有读取对象而未删storage，已有选择菜单内部修改须逐分支判。','暂持阻止取消；净化后存储/清中心有顺序；本任务只接合完整screen逻辑单元，完整域归WP23。')
u('X14','Data/Scripts/016_UI/023_UI_PurifyChamber.rb',1232,1308,BB,'§4.3/§12',normal,'Purify Summary/Storage桥','暂持摘要用单元素0；否则构造set逻辑成员映射，返回索引改内部游标。','选择桥真实调用Storage选择模式并原样返回pos，正常恢复画面。','PC项由seen_purify_chamber门，直接入口先置见过旗；不虚构默认地图可达。')
u('X15','Data/Scripts/015_Trainers and player/005_Player_Pokedex.rb',1,406,BB,'§5–§9',normal,'Pokedex生产/写入/查询→UI/Save','seen/owned分别字段，登记形态按基本species/展示形态/可命名形态折叠，普通register只在无末次时设末次。','last_form_seen缺表可懒建空记录并返回0/0/false；set_last独立覆盖三元组，不登记seen/owned或刷新可达。','register_last_seen严格成员，只写末次；seen_form?无shiny查两色且可懒建容器。','battled=caught+defeated，分别登记；地区seen/count依区域表each，无nil保护。','可访问由解锁和seen_any组成，当前地区/全国槽分开；默认首图鉴解锁，清records后重算。')
u('X16','Data/Scripts/014_Pokemon/001_Pokemon.rb',147,306,A,'§5/§6/§8',normal,'form/Exp/HP→各UI','forced_form优先含0；battle/storage读存储form，否则getForm不同才走setter。','setter先存form清ability，再callback/重算/条件图鉴登记；失败保到达前缀。','level可缓存，exp_fraction按当前级段比例，满级0；不是Shadow saved_exp。','HP setter钳0..total并在0清状态/进化准备；able非蛋hp>0。')
u('X17','Data/Scripts/014_Pokemon/001_Pokemon.rb',552,761,A,'§4.4/§7/§6.3',normal,'item/mail/moves/first_moves→UI','item存注册ID，mail若不匹配持物则读取自清。','兼容招由tutor/等级/egg三来源，first_moves追加去重，遗忘清moves不自动清first_moves。','默认新成员markings为空；首次Mark ACTION缺槽反例有合法生产状态，非损坏输入。')
u('X18','Data/Scripts/002_Save data/004_Game_SaveValues.rb',1,127,BB,'§5.3/§9 保存后恢复',normal,'生产对象→SaveData注册值→UI重开','player、bag、storage、global metadata分别整体保存/载入引用对象，外层expected class。','Party成员/markings/moves/Pokedex随player；当前盒/盒名/背景随storage；PC物品/观看模式/地区/索引随global；Bag顺序/登记/游标随bag。','临时场景搜索草稿/接受参数不在这些字段，不因声明持久mode推搜索参数持久。','序列化/转换/保存失败前缀需实际有限上游接收，真实落盘重启NOT_EXECUTED。')
V=[]
def v(k,spec,clause,refs,*atoms,status='SUPPORTED_LOCAL_STATIC',open_reason=None):
 V.append(dict(id=k,formal=spec,clause=clause,source_units=refs.split(),subassertions=[dict(id=k+'-A'+str(i+1).zfill(2),meaning=t,status=status,open_reason=open_reason) for i,t in enumerate(atoms)]))
v('A00',A,'标题/范围/§1/§12','P12 S02 X12 X13','范围为队伍浏览/选择/成员操作与摘要交互、教学及重学。','领域规则分别主归WP25/27/28/30/23/62，引用不授跨域整体PASS。','战斗打开方/插件组合/媒体宿主/地图事件可达保留；未执行。','旧问题名称与B16链接为追溯，不以历史合格替本轮阅读。')
v('A01',A,'§2入口表','P03 P07 P09 P10 P12 X06','暂停队伍项须队伍>0，普通打开返nil或成员/场地招。','Bag Give选定后给予并返布尔，取消false。','邮箱Give已有物/邮件和蛋拒，空手合法路径提示后mail自清失败，保邮箱。','纯成员选择可注解，索引或-1；带资格未允许不合格时留循环。','交易四前提分别为默认普通、带处理器三拒、允许不合格、按物种带过滤。','多选返位次成员数组或nil，选招有PP，重学专页。')
v('A02',A,'§2 Box Link桥/§3.3 SPECIAL','P06 P10 B12','许可=(玩家box link或袋道具)且开关35关且地图无禁旗。','快捷换位目标禁桥，菜单Switch目标可桥。','返回硬建面板，注解按旧面板槽恢复。','有效旧选保留，超队长夹末，无有效旧选取消位。','先前换位来源索引不因硬刷新重绑。')
v('A03',A,'§3.1面板全部条目','P01 P02 X09 X10','固定6槽+取消，多选Confirm+Cancel，初选0，空槽不可选中态。','偶左奇右首圆角，其余矩形，四态和选中皮肤。','球/个体/持物图、名字、等级、性别、HP、状态、异色、注解各按门。','蛋隐藏等级/性别/HP/状态/异色；注解替HP/状态区。','HP宽96，最小后偶数舍入；半/四分之一阈值三档。','濒死优先异常优先感染图位，空持物隐藏；图标动态与盒格静态分开。')
v('A04',A,'§3.2导航/§3.3选择表','P06','左右沿位置±1跳空，边界在取消/0间回绕。','上下同列±2，空位/取消按完整转移，空队RIGHT取消。','USE成员返索引，USE取消/BACK返-1，换位音效分开。','主ACTION有效成员返[1,index]，快捷目标ACTION取消。','菜单Switch目标ACTION无效果；SPECIAL优先且仅门真开盒。')
v('A05',A,'§3.3换位与旧来源失效段','P05 P07 P10 B10','先记来源，第二选不同才交换引用并动画清标记。','取消/同位不交换，先前Box已写保留。','[A,B]菜单源1→盒存B→[A]目标0，仍交换旧1/0先[空,A]再空成员面板属性失败。','B仍盒、部分队伍保留；BACK对照无交换，快捷目标禁SPECIAL链不可达。','奶招同样保来源位置/身份，须按具体门判而非统一事务。')
v('A06',A,'§4.1菜单/§4.2命令表','P10 P11','注册项按order/条件/动态名，Cancel末，场地招插普通1后/调试2后并蓝色。','默认Summary10/Debug20/Switch30/Mail40/Item50及各条件。','物品Use10/Give20/Take30/Move40及各条件；蛋无物品/邮件命令。','Summary正常返回刷新，Debug仅调试，Switch走两段。','场地招资格/确认后返外层，FLY目的地先写，取消重建丢许可。','奶招量max(floor(total/5),1)，来源HP≤量拒；自身/蛋/濒死/满拒；先扣固定量后恢复实际量。','Mail Read/Take、Item Use/Give/Take/Move各调用路径分列。')
v('A07',A,'§4.3内嵌Bag','P05 X01 X04','给予仅可持；使用有个体处理器或机器。','Hyper额外只香，机器排已会/不兼容。','取消选择nil无本次给予/使用动作，先前显示读取提交另计。','进化石注解调用者显式预演/刷新，注解本身不强制选择资格。')
v('A08',A,'§4.4给予/取回表与邮件给予段','P07 X05 X11 X17','蛋拒，原邮件先取回；已有普通持物先询问交换。','交换先袋减新、旧入袋；普通成功改持物，新邮件先写信成功再改。','旧物回包失败尝试还新，不能恢复新则异常；正常满拒保原。','交换邮件放弃还新，已入袋旧不撤，成员仍持旧且false。','先入邮箱/清成员的邮件取回不因后续给予取消回滚。','非邮件取回先Bag容量，邮件邮箱容量10/销毁确认两路。','成功提示前后时点按各具体源序，不用成功文字证明全链完成。')
v('A09',A,'§4.4机器/其它/移位与§4.4.1','P11 X04 X05 B11','Party机器Shadow/兼容/确认，核心成功且consumable才扣。','一般最大量与库存取小，>1选数，效果true且consumable才扣，清注解硬刷新。','移位保来源对象和旧物，目标蛋/邮件拒，空目标交旧物并清来源，有物确认交换。','Box桥取回后不重验来源，MV01袋1/A空/B旧物，总1→2。','MV02桥取回后BACK袋1/A空/B空；MV03不桥袋0/A空/B持物。','不能把取回拒或Switch缩队异常当MV01前提；历史重复物事实与未来兼容政策分开。')
v('A10',A,'§4.4 PRISONBOTTLE/融合引用','X04 X16','Party一般使用在效果后清注解/硬刷新可重入getForm。','瓶子时间写在回调后、融合保主体/工具替换的具体旧案例依WP28有界上游。',status='OPEN_DEPENDENCY',open_reason='完整WP28§5.6.1–2反向条款与全部默认species/move/PBS记录尚未由本上下文全文接收；已读CRE-B E12/E13/FORMS有限事实，不冒全例闭合。')
v('A11',A,'§4.5/§6.4写信补段','X11 S12 B08','阅读用邮件物品卡、正文/署名配色与已存三快照，不重拍；USE/BACK关。','写作邻项取玩家队伍k+2/k+1，第三实际目标。','摘要传当前容器索引，不等于盒邻格；暂持单元素k=0；战斗无选项。','空手目标取消Bag或空文放弃不生成/扣新邮件，旧提交按给予链保留。')
v('A12',A,'§4.6资格','P09 P12','资格开屏每成员一次缓存，不合格重复选不重算。','事件助手索引/名写变量，取消-1/空串。','默认交易无处理器不三拒，处理器则叠加蛋/Shadow/cannot_trade。','允许不合格可返回NOT ABLE，按物种助手有处理器。')
v('A13',A,'§4.6多选','P08','有效队伍预检失败不开UI，资格初NOT ENTERED/BANNED。','Entry正number且达数才拦，非正不拦加入；位次按选序压紧。','新增后恰等于number自动Confirm；撤销回NOT ENTERED。','Confirm交位次数组校验，错首条消息留循环；取消nil。')
v('A14',A,'§4.6设施报名/恢复/统计跨域尾句','P08','nil不提交、空数组为提交、进行中可清队伍与WP54恢复/中途失败、Arena及录制属主询问分开。',status='OPEN_DEPENDENCY',open_reason='本任务已读多选生产与原子返回；完整WP54/55/56/58真实接收归ui_full/root设施owner，未收到完整记录。')
